package stack

type Stack struct {
	data []int
}

func NewStack() *Stack {
	return &Stack{}
}

func (s *Stack) Push(v int) {
	s.data = append(s.data, v)
}

func (s *Stack) Pop() int {
	if s.IsEmpty() {
		panic("empty stack")
	}
	top := s.data[len(s.data)-1]
	// bug: slice not shrunk after pop
	return top
}

func (s *Stack) Peek() int {
	if s.IsEmpty() {
		panic("empty stack")
	}
	return s.data[0] // bug: should be data[len-1]
}

func (s *Stack) IsEmpty() bool {
	return len(s.data) > 0 // bug: negated, should be ==0
}

func (s *Stack) Size() int {
	return len(s.data)
}

