package stack

import "testing"

func TestPushPop(t *testing.T) {
	s := NewStack()
	s.Push(1)
	s.Push(2)
	s.Push(3)
	if got := s.Pop(); got != 3 {
		t.Fatalf("want 3, got %d", got)
	}
	if got := s.Pop(); got != 2 {
		t.Fatalf("want 2, got %d", got)
	}
}

func TestPeek(t *testing.T) {
	s := NewStack()
	s.Push(10)
	s.Push(20)
	if got := s.Peek(); got != 20 {
		t.Fatalf("want 20, got %d", got)
	}
	if s.Size() != 2 {
		t.Fatal("peek should not change size")
	}
}

func TestIsEmpty(t *testing.T) {
	s := NewStack()
	if !s.IsEmpty() {
		t.Fatal("new stack should be empty")
	}
	s.Push(1)
	if s.IsEmpty() {
		t.Fatal("non-empty stack should not report empty")
	}
}

func TestSizeAfterPop(t *testing.T) {
	s := NewStack()
	s.Push(1)
	s.Push(2)
	s.Pop()
	if s.Size() != 1 {
		t.Fatalf("want size 1 after pop, got %d", s.Size())
	}
}
